func (o *StatRecord) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Match":
		rel, ok := retrieved.(*Match)
		if !ok {
			return fmt.Errorf("statRecord cannot load %T as %q", retrieved, name)
		}

		o.R.Match = rel
		o.R.Loaded.Match = true

		if rel != nil {
			rel.R.StatRecords = StatRecordSlice{o}
		}
		return nil
	case "Player":
		rel, ok := retrieved.(*Player)
		if !ok {
			return fmt.Errorf("statRecord cannot load %T as %q", retrieved, name)
		}

		o.R.Player = rel
		o.R.Loaded.Player = true

		if rel != nil {
			rel.R.StatRecords = StatRecordSlice{o}
		}
		return nil
	case "Round":
		rel, ok := retrieved.(*Round)
		if !ok {
			return fmt.Errorf("statRecord cannot load %T as %q", retrieved, name)
		}

		o.R.Round = rel
		o.R.Loaded.Round = true

		if rel != nil {
			rel.R.StatRecords = StatRecordSlice{o}
		}
		return nil
	case "Stat":
		rel, ok := retrieved.(*Stat)
		if !ok {
			return fmt.Errorf("statRecord cannot load %T as %q", retrieved, name)
		}

		o.R.Stat = rel
		o.R.Loaded.Stat = true

		if rel != nil {
			rel.R.StatRecords = StatRecordSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("statRecord has no relationship %q", name)
	}
}

