func buildStatRecordThenLoader[Q orm.Loadable]() statRecordThenLoader[Q] {
	type MatchLoadInterface interface {
		LoadMatch(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type PlayerLoadInterface interface {
		LoadPlayer(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type RoundLoadInterface interface {
		LoadRound(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type StatLoadInterface interface {
		LoadStat(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return statRecordThenLoader[Q]{
		Match: thenLoadBuilder[Q](
			"Match",
			func(ctx context.Context, exec bob.Executor, retrieved MatchLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadMatch(ctx, exec, mods...)
			},
		),
		Player: thenLoadBuilder[Q](
			"Player",
			func(ctx context.Context, exec bob.Executor, retrieved PlayerLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadPlayer(ctx, exec, mods...)
			},
		),
		Round: thenLoadBuilder[Q](
			"Round",
			func(ctx context.Context, exec bob.Executor, retrieved RoundLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadRound(ctx, exec, mods...)
			},
		),
		Stat: thenLoadBuilder[Q](
			"Stat",
			func(ctx context.Context, exec bob.Executor, retrieved StatLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadStat(ctx, exec, mods...)
			},
		),
	}
}

// LoadMatch loads the statRecord's Match into the .R struct
func (o *StatRecord) LoadMatch(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Match = nil
	o.R.Loaded.Match = false

	related, err := o.Match(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.StatRecords = StatRecordSlice{o}

	o.R.Match = related
	o.R.Loaded.Match = true
	return nil
}

// LoadMatch loads the statRecord's Match into the .R struct
func (os StatRecordSlice) LoadMatch(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	matches, err := os.Match(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Match = nil
		o.R.Loaded.Match = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	statRecordByKey := make(map[int64][]*StatRecord, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		statRecordByKey[o.MatchID] = append(statRecordByKey[o.MatchID], o)
	}

	for _, rel := range matches {

		owners, ok := statRecordByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Match != nil {
				continue
			}

			rel.R.StatRecords = append(rel.R.StatRecords, o)

			o.R.Match = rel

		}
	}

	return nil
}

